              if coalesce(s.accommodation_charge_ex_vat,0) <> 0 or coalesce(s.accommodation_pay_ex_vat,0) <> 0 then
                pay_ex := public._inv_round2(coalesce(s.accommodation_pay_ex_vat,0));
