            if coalesce(s.mileage_units,0) <> 0 or coalesce(s.mileage_charge_ex_vat,0) <> 0 or coalesce(s.mileage_pay_ex_vat,0) <> 0 then
              unit_count := public._inv_round2(coalesce(s.mileage_units,0));
