              end if;



                     end loop;
            -- -------------------------
            -- EXPENSES lines (per category; only if category charge>0)
            -- NOTE:
            --   - Amounts come from TSFIN category columns:
            --       travel_*, accommodation_*, other_*
            --   - expenses_description is treated as NOTES only (optionally JSON).
            --   - Evidence is enforced by v_ts_invoice_precheck (timesheet_evidence.kind).
            -- -------------------------
            declare
              v_desc_txt text := null;
              v_desc_json jsonb := null;

              v_note_global text := null;
              v_note_travel text := null;
              v_note_accom  text := null;
              v_note_other  text := null;
            begin
              v_desc_txt := nullif(btrim(coalesce(snap.expenses_description,'')), '');

              if v_desc_txt is not null and left(v_desc_txt, 1) = '{' then
                begin
                  v_desc_json := v_desc_txt::jsonb;
                exception when others then
                  v_desc_json := null;
                end;

                if v_desc_json is not null and jsonb_typeof(v_desc_json) = 'object' then
                  v_note_global := nullif(btrim(coalesce(v_desc_json->>'note','')), '');

                  v_note_travel := nullif(btrim(coalesce(
                    v_desc_json #>> '{travel,note}',
                    v_desc_json->>'travel_note',
                    v_desc_json->>'travel',
                    ''
                  )), '');

                  v_note_accom := nullif(btrim(coalesce(
                    v_desc_json #>> '{accommodation,note}',
                    v_desc_json->>'accommodation_note',
                    v_desc_json->>'accommodation',
                    ''
                  )), '');

                  v_note_other := nullif(btrim(coalesce(
                    v_desc_json #>> '{other,note}',
                    v_desc_json->>'other_note',
                    v_desc_json->>'other',
                    ''
                  )), '');

                  if v_note_global is not null then
                    if v_note_travel is null then v_note_travel := v_note_global; end if;
                    if v_note_accom  is null then v_note_accom  := v_note_global; end if;
                    if v_note_other  is null then v_note_other  := v_note_global; end if;
                  end if;
                else
                  v_note_travel := v_desc_txt;
                  v_note_accom  := v_desc_txt;
                  v_note_other  := v_desc_txt;
                end if;
              else
                v_note_travel := v_desc_txt;
                v_note_accom  := v_desc_txt;
                v_note_other  := v_desc_txt;
              end if;

              -- TRAVEL
              if coalesce(snap.travel_charge_ex_vat,0) <> 0 or coalesce(snap.travel_pay_ex_vat,0) <> 0 then
                v_any_expense_line := true;
                pay_ex := public._inv_round2(coalesce(snap.travel_pay_ex_vat,0));
                chg_ex := public._inv_round2(coalesce(snap.travel_charge_ex_vat,0));
                margin_ex := public._inv_round2(chg_ex - pay_ex);
                vat_amt := public._inv_round2(chg_ex * v_vat_rate / 100);
                inc_amt := public._inv_round2(chg_ex + vat_amt);

                line_desc :=
                  'Travel expenses'
                  || case when v_note_travel is not null then ' – ' || v_note_travel else '' end
                  || case when snap.week_ending_date is not null then ' (W/E ' || snap.week_ending_date::text || ')' else '' end;

                meta := jsonb_build_object(
                  'line_type','EXPENSE_TRAVEL',
                  'timesheet_id', v_ts_id::text,
                  'tsfin_id', snap.id::text,
                  'candidate_display', cand_display,
                  'role', con_role,
                  'hospital', con_display_site,
                  'ward', con_ward_hint,
                  'week_ending_date', snap.week_ending_date::text,
                  'expense', jsonb_build_object(
                    'category', 'TRAVEL',
                    'note', v_note_travel,
                    'pay_ex_vat', pay_ex,
                    'charge_ex_vat', chg_ex
                  ),
                  'totals', jsonb_build_object(
                    'line_pay_ex_vat', pay_ex,
                    'line_charge_ex_vat', chg_ex,
                    'margin_ex_vat', margin_ex,
                    'vat_rate_pct', v_vat_rate,
                    'vat_amount', vat_amt,
                    'total_inc_vat', inc_amt
                  )
                );

                v_line_source_key := 'TS:' || v_ts_id::text || ':EXP:TRAVEL';

                insert into public.invoice_lines(
                  invoice_id, timesheet_id, booking_id, description,
                  hours_day, hours_night, hours_sat, hours_sun, hours_bh,
                  pay_day, pay_night, pay_sat, pay_sun, pay_bh,
                  charge_day, charge_night, charge_sat, charge_sun, charge_bh,
                  total_pay_ex_vat, total_charge_ex_vat, margin_ex_vat,
                  vat_rate_pct, vat_amount, total_inc_vat,
                  paper_ts_r2_key, meta_json, source_key
                )
                values (
                  v_invoice_id, v_ts_id, snap.booking_id, line_desc,
                  0,0,0,0,0,
                  null,null,null,null,null,
      coalesce(snap.charge_day,null),
      coalesce(snap.charge_night,null),
      coalesce(snap.charge_sat,null),
      coalesce(snap.charge_sun,null),
      coalesce(snap.charge_bh,null),

                  pay_ex, chg_ex, margin_ex,
                  v_vat_rate, vat_amt, inc_amt,
                  ('docs-pdf/timesheets/ts_' || v_ts_id::text || '.pdf'),
                  meta,
                  v_line_source_key
                )
                on conflict (invoice_id, source_key) do nothing;

                if found then
                  insert into pg_temp._inv_run_lines(timesheet_id, source_key, charge_ex, vat_amount, inc_amount)
                  values (v_ts_id, v_line_source_key, chg_ex, vat_amt, inc_amt);
                end if;
              end if;

              -- ACCOMMODATION
              if coalesce(snap.accommodation_charge_ex_vat,0) <> 0 or coalesce(snap.accommodation_pay_ex_vat,0) <> 0 then
                v_any_expense_line := true;
                pay_ex := public._inv_round2(coalesce(snap.accommodation_pay_ex_vat,0));
                chg_ex := public._inv_round2(coalesce(snap.accommodation_charge_ex_vat,0));
                margin_ex := public._inv_round2(chg_ex - pay_ex);
                vat_amt := public._inv_round2(chg_ex * v_vat_rate / 100);
                inc_amt := public._inv_round2(chg_ex + vat_amt);

                line_desc :=
                  'Accommodation expenses'
                  || case when v_note_accom is not null then ' – ' || v_note_accom else '' end
                  || case when snap.week_ending_date is not null then ' (W/E ' || snap.week_ending_date::text || ')' else '' end;

                meta := jsonb_build_object(
                  'line_type','EXPENSE_ACCOMMODATION',
                  'timesheet_id', v_ts_id::text,
                  'tsfin_id', snap.id::text,
                  'candidate_display', cand_display,
                  'role', con_role,
                  'hospital', con_display_site,
                  'ward', con_ward_hint,
                  'week_ending_date', snap.week_ending_date::text,
                  'expense', jsonb_build_object(
                    'category', 'ACCOMMODATION',
                    'note', v_note_accom,
                    'pay_ex_vat', pay_ex,
                    'charge_ex_vat', chg_ex
                  ),
                  'totals', jsonb_build_object(
                    'line_pay_ex_vat', pay_ex,
                    'line_charge_ex_vat', chg_ex,
                    'margin_ex_vat', margin_ex,
                    'vat_rate_pct', v_vat_rate,
                    'vat_amount', vat_amt,
                    'total_inc_vat', inc_amt
                  )
                );

                v_line_source_key := 'TS:' || v_ts_id::text || ':EXP:ACCOMMODATION';

                insert into public.invoice_lines(
                  invoice_id, timesheet_id, booking_id, description,
                  hours_day, hours_night, hours_sat, hours_sun, hours_bh,
                  pay_day, pay_night, pay_sat, pay_sun, pay_bh,
                  charge_day, charge_night, charge_sat, charge_sun, charge_bh,
                  total_pay_ex_vat, total_charge_ex_vat, margin_ex_vat,
                  vat_rate_pct, vat_amount, total_inc_vat,
                  paper_ts_r2_key, meta_json, source_key
                )
                values (
                  v_invoice_id, v_ts_id, snap.booking_id, line_desc,
                  0,0,0,0,0,
                  null,null,null,null,null,
      coalesce(snap.charge_day,null),
      coalesce(snap.charge_night,null),
      coalesce(snap.charge_sat,null),
      coalesce(snap.charge_sun,null),
      coalesce(snap.charge_bh,null),

                  pay_ex, chg_ex, margin_ex,
                  v_vat_rate, vat_amt, inc_amt,
                  ('docs-pdf/timesheets/ts_' || v_ts_id::text || '.pdf'),
                  meta,
                  v_line_source_key
                )
                on conflict (invoice_id, source_key) do nothing;

                if found then
                  insert into pg_temp._inv_run_lines(timesheet_id, source_key, charge_ex, vat_amount, inc_amount)
                  values (v_ts_id, v_line_source_key, chg_ex, vat_amt, inc_amt);
                end if;
              end if;

              -- OTHER
              if coalesce(snap.other_charge_ex_vat,0) <> 0 or coalesce(snap.other_pay_ex_vat,0) <> 0 then
                v_any_expense_line := true;
                pay_ex := public._inv_round2(coalesce(snap.other_pay_ex_vat,0));
                chg_ex := public._inv_round2(coalesce(snap.other_charge_ex_vat,0));
                margin_ex := public._inv_round2(chg_ex - pay_ex);
                vat_amt := public._inv_round2(chg_ex * v_vat_rate / 100);
                inc_amt := public._inv_round2(chg_ex + vat_amt);

                line_desc :=
                  'Other expenses'
                  || case when v_note_other is not null then ' – ' || v_note_other else '' end
                  || case when snap.week_ending_date is not null then ' (W/E ' || snap.week_ending_date::text || ')' else '' end;

                meta := jsonb_build_object(
                  'line_type','EXPENSE_OTHER',
                  'timesheet_id', v_ts_id::text,
                  'tsfin_id', snap.id::text,
                  'candidate_display', cand_display,
                  'role', con_role,
                  'hospital', con_display_site,
                  'ward', con_ward_hint,
                  'week_ending_date', snap.week_ending_date::text,
                  'expense', jsonb_build_object(
                    'category', 'OTHER',
                    'note', v_note_other,
                    'pay_ex_vat', pay_ex,
                    'charge_ex_vat', chg_ex
                  ),
                  'totals', jsonb_build_object(
                    'line_pay_ex_vat', pay_ex,
                    'line_charge_ex_vat', chg_ex,
                    'margin_ex_vat', margin_ex,
                    'vat_rate_pct', v_vat_rate,
                    'vat_amount', vat_amt,
                    'total_inc_vat', inc_amt
                  )
                );

                v_line_source_key := 'TS:' || v_ts_id::text || ':EXP:OTHER';

                insert into public.invoice_lines(
                  invoice_id, timesheet_id, booking_id, description,
                  hours_day, hours_night, hours_sat, hours_sun, hours_bh,
                  pay_day, pay_night, pay_sat, pay_sun, pay_bh,
                  charge_day, charge_night, charge_sat, charge_sun, charge_bh,
                  total_pay_ex_vat, total_charge_ex_vat, margin_ex_vat,
                  vat_rate_pct, vat_amount, total_inc_vat,
                  paper_ts_r2_key, meta_json, source_key
                )
                values (
                  v_invoice_id, v_ts_id, snap.booking_id, line_desc,
                  0,0,0,0,0,
                  null,null,null,null,null,
      coalesce(snap.charge_day,null),
      coalesce(snap.charge_night,null),
      coalesce(snap.charge_sat,null),
      coalesce(snap.charge_sun,null),
      coalesce(snap.charge_bh,null),

                  pay_ex, chg_ex, margin_ex,
                  v_vat_rate, vat_amt, inc_amt,
                  ('docs-pdf/timesheets/ts_' || v_ts_id::text || '.pdf'),
                  meta,
                  v_line_source_key
                )
                on conflict (invoice_id, source_key) do nothing;

                if found then
                  insert into pg_temp._inv_run_lines(timesheet_id, source_key, charge_ex, vat_amount, inc_amount)
                  values (v_ts_id, v_line_source_key, chg_ex, vat_amt, inc_amt);
                end if;
              end if;

              -- EXPENSES TOTAL (fallback): if we have expenses totals but no category lines,
              -- write a single aggregate expense line so expenses-only timesheets can invoice.
              if v_any_expense_line is false and (coalesce(snap.expenses_charge_ex_vat,0) <> 0 or coalesce(snap.expenses_pay_ex_vat,0) <> 0) then
                pay_ex := public._inv_round2(coalesce(snap.expenses_pay_ex_vat,0));
                chg_ex := public._inv_round2(coalesce(snap.expenses_charge_ex_vat,0));
                margin_ex := public._inv_round2(chg_ex - pay_ex);
                vat_amt := public._inv_round2(chg_ex * v_vat_rate / 100);
                inc_amt := public._inv_round2(chg_ex + vat_amt);

                line_desc :=
                  'Expenses'
                  || case
                       when nullif(btrim(coalesce(snap.expenses_description,'')), '') is not null then ' – ' || nullif(btrim(coalesce(snap.expenses_description,'')), '')
                       when v_note_global is not null then ' – ' || v_note_global
                       else ''
                     end
                  || case when snap.week_ending_date is not null then ' (W/E ' || snap.week_ending_date::text || ')' else '' end;

                meta := jsonb_build_object(
                  'line_type','EXPENSES_TOTAL',
                  'timesheet_id', v_ts_id::text,
                  'tsfin_id', snap.id::text,
                  'candidate_display', cand_display,
                  'role', con_role,
                  'hospital', con_display_site,
                  'ward', con_ward_hint,
                  'week_ending_date', snap.week_ending_date::text,
                  'expense', jsonb_build_object(
                    'category', 'EXPENSES',
                    'note', nullif(btrim(coalesce(snap.expenses_description,'')), ''),
                    'pay_ex_vat', pay_ex,
                    'charge_ex_vat', chg_ex,
                    'evidence_r2_key', snap.expenses_evidence_r2_key,
                    'evidence_manifest', snap.expenses_evidence_manifest
                  ),
                  'totals', jsonb_build_object(
                    'line_pay_ex_vat', pay_ex,
                    'line_charge_ex_vat', chg_ex,
                    'margin_ex_vat', margin_ex,
                    'vat_rate_pct', v_vat_rate,
                    'vat_amount', vat_amt,
                    'total_inc_vat', inc_amt
                  )
                );

                v_line_source_key := 'TS:' || v_ts_id::text || ':EXP:TOTAL';

                insert into public.invoice_lines(
                  invoice_id, timesheet_id, booking_id, description,
                  hours_day, hours_night, hours_sat, hours_sun, hours_bh,
                  pay_day, pay_night, pay_sat, pay_sun, pay_bh,
                  charge_day, charge_night, charge_sat, charge_sun, charge_bh,
                  total_pay_ex_vat, total_charge_ex_vat, margin_ex_vat,
                  vat_rate_pct, vat_amount, total_inc_vat,
                  paper_ts_r2_key, meta_json, source_key
                )
                values (
                  v_invoice_id, v_ts_id, snap.booking_id, line_desc,
                  0,0,0,0,0,
                  null,null,null,null,null,
                  coalesce(snap.charge_day,null),
                  coalesce(snap.charge_night,null),
                  coalesce(snap.charge_sat,null),
                  coalesce(snap.charge_sun,null),
                  coalesce(snap.charge_bh,null),
                  pay_ex, chg_ex, margin_ex,
                  v_vat_rate, vat_amt, inc_amt,
                  ('docs-pdf/timesheets/ts_' || v_ts_id::text || '.pdf'),
                  meta,
                  v_line_source_key
                )
                on conflict (invoice_id, source_key) do nothing;

                if found then
                  insert into pg_temp._inv_run_lines(timesheet_id, source_key, charge_ex, vat_amount, inc_amount)
                  values (v_ts_id, v_line_source_key, chg_ex, vat_amt, inc_amt);
                end if;
              end if;
            end;


            -- -------------------------
            -- MILEAGE line (one per timesheet, if charge>0)
            -- -------------------------
            if coalesce(snap.mileage_units,0) <> 0 or coalesce(snap.mileage_charge_ex_vat,0) <> 0 or coalesce(snap.mileage_pay_ex_vat,0) <> 0 then
              unit_count := public._inv_round2(coalesce(snap.mileage_units,0));
              pay_rate := coalesce(snap.mileage_pay_rate,0);
              charge_rate := coalesce(snap.mileage_charge_rate,0);

              pay_ex := public._inv_round2(coalesce(snap.mileage_pay_ex_vat,0));
              chg_ex := public._inv_round2(coalesce(snap.mileage_charge_ex_vat,0));
              margin_ex := public._inv_round2(chg_ex - pay_ex);
              vat_amt := public._inv_round2(chg_ex * v_vat_rate / 100);
              inc_amt := public._inv_round2(chg_ex + vat_amt);

              line_desc :=
                'Mileage – ' || unit_count::text || ' miles' ||
                case when charge_rate is not null then ' @ £' || to_char(charge_rate::numeric, 'FM999999990.00') else '' end ||
                case when snap.week_ending_date is not null then ' (W/E ' || snap.week_ending_date::text || ')' else '' end;

              meta := jsonb_build_object(
                'line_type','MILEAGE',
                'timesheet_id', v_ts_id::text,
                'tsfin_id', snap.id::text,
                'candidate_display', cand_display,
                'role', con_role,
                'hospital', con_display_site,
                'ward', con_ward_hint,
                'week_ending_date', snap.week_ending_date::text,
                'mileage', jsonb_build_object(
                  'mileage_units', unit_count,
                  'pay_rate', pay_rate,
                  'charge_rate', charge_rate,
                  'evidence_r2_key', snap.mileage_evidence_r2_key,
                  'evidence_manifest', snap.mileage_evidence_manifest
                ),
                'totals', jsonb_build_object(
                  'line_pay_ex_vat', pay_ex,
                  'line_charge_ex_vat', chg_ex,
                  'margin_ex_vat', margin_ex,
                  'vat_rate_pct', v_vat_rate,
                  'vat_amount', vat_amt,
                  'total_inc_vat', inc_amt
                )
              );

              v_line_source_key := 'TS:' || v_ts_id::text || ':MILEAGE';

              insert into public.invoice_lines(
                invoice_id, timesheet_id, booking_id, description,
                hours_day, hours_night, hours_sat, hours_sun, hours_bh,
                pay_day, pay_night, pay_sat, pay_sun, pay_bh,
                charge_day, charge_night, charge_sat, charge_sun, charge_bh,
                total_pay_ex_vat, total_charge_ex_vat, margin_ex_vat,
                vat_rate_pct, vat_amount, total_inc_vat,
                paper_ts_r2_key, meta_json, source_key
              )
              values (
                v_invoice_id, v_ts_id, snap.booking_id, line_desc,
                0,0,0,0,0,
                null,null,null,null,null,
      coalesce(snap.charge_day,null),
      coalesce(snap.charge_night,null),
      coalesce(snap.charge_sat,null),
      coalesce(snap.charge_sun,null),
      coalesce(snap.charge_bh,null),

                pay_ex, chg_ex, margin_ex,
                v_vat_rate, vat_amt, inc_amt,
                ('docs-pdf/timesheets/ts_' || v_ts_id::text || '.pdf'),
                meta,
                v_line_source_key
              )
              on conflict (invoice_id, source_key) do nothing;

              if found then
                insert into pg_temp._inv_run_lines(timesheet_id, source_key, charge_ex, vat_amount, inc_amount)
                values (v_ts_id, v_line_source_key, chg_ex, vat_amt, inc_amt);
              end if;
            end if;

          end loop; -- per timesheet


          if not exists (select 1 from public.invoice_lines where invoice_id = v_invoice_id) then
            raise exception 'Nothing to invoice (all billable amounts are zero after daily/weekly rules).';
          end if;

             -- Totals: recompute from all lines (matches end outcome; avoids additive drift)

      update public.invoices i
      set
        subtotal_ex_vat = x.ex,
        vat_amount      = x.vat,
        total_inc_vat   = x.inc,
        updated_at      = v_now
      from (
        select
          coalesce(sum(l.total_charge_ex_vat),0)::numeric as ex,
          coalesce(sum(l.vat_amount),0)::numeric as vat,
          coalesce(sum(l.total_inc_vat),0)::numeric as inc
        from public.invoice_lines l
        where l.invoice_id = v_invoice_id
      ) x
      where i.id = v_invoice_id;

      -- Compute NEW totals and delta (NEW - PREV)
      select
        coalesce(i.subtotal_ex_vat,0)::numeric,
        coalesce(i.vat_amount,0)::numeric,
        coalesce(i.total_inc_vat,0)::numeric
      into v_new_ex, v_new_vat, v_new_inc
      from public.invoices i
      where i.id = v_invoice_id
      limit 1;

      v_delta_ex  := public._inv_round2(v_new_ex  - v_prev_ex);
      v_delta_vat := public._inv_round2(v_new_vat - v_prev_vat);
      v_delta_inc := public._inv_round2(v_new_inc - v_prev_inc);

      select
        array_agg(distinct rl.timesheet_id),
        array_agg(distinct rl.source_key),
        count(*)::int
      into
        v_run_ts_ids,
        v_run_source_keys,
        v_run_line_count
      from pg_temp._inv_run_lines rl;

      if v_invoice_debug then
        v_dbg_grp_i := coalesce(v_dbg_grp_i,0) + 1;
        v_dbg_groups_detail := v_dbg_groups_detail || jsonb_build_array(
          jsonb_build_object(
            'group_index', v_dbg_grp_i,
            'consolidation_mode', v_consol_mode,
            'mode', v_mode,
            'all_selfbill', coalesce(v_all_selfbill,false),

            'ts_ids', to_jsonb(coalesce(v_ts_ids_to_use, array[]::uuid[])),
            'ts_id_count', coalesce(array_length(v_ts_ids_to_use,1),0),
            'entry_count', coalesce(v_entry_count,0),

            'invoice_id', case when v_invoice_id is null then null else v_invoice_id::text end,
            'invoice_created', coalesce(v_created,false),
            'invoice_status_before', v_prev_status,
            'invoice_status_after', (select i.status::text from public.invoices i where i.id = v_invoice_id limit 1),

            'prev_totals', jsonb_build_object(
              'subtotal_ex_vat', public._inv_round2(v_prev_ex),
              'vat_amount', public._inv_round2(v_prev_vat),
              'total_inc_vat', public._inv_round2(v_prev_inc)
            ),
            'new_totals', jsonb_build_object(
              'subtotal_ex_vat', public._inv_round2(v_new_ex),
              'vat_amount', public._inv_round2(v_new_vat),
              'total_inc_vat', public._inv_round2(v_new_inc)
            ),
            'delta_totals', jsonb_build_object(
              'subtotal_ex_vat', v_delta_ex,
              'vat_amount', v_delta_vat,
              'total_inc_vat', v_delta_inc
            ),

            'this_run', jsonb_build_object(
              'timesheet_ids', to_jsonb(coalesce(v_run_ts_ids, array[]::uuid[])),
              'source_keys', to_jsonb(coalesce(v_run_source_keys, array[]::text[])),
              'line_count', coalesce(v_run_line_count,0)
            )
          )
        );
      end if;

      -- Write ONE audit row that proves this run + what changed (including later append runs)
      if (coalesce(v_delta_ex,0) <> 0 or coalesce(v_delta_vat,0) <> 0 or coalesce(v_delta_inc,0) <> 0) then
        perform public._inv_write_audit(
          p_actor_user_id,
          'INVOICE_TOTALS_DELTA_APPLIED',
          jsonb_build_object(
            'outbox_id', v_outbox_id::text,
            'job_kind', v_kind,
            'run_at_utc', public._inv_iso_utc(v_now),

            'invoice_id', v_invoice_id::text,
            'invoice_no', v_prev_invoice_no,
            'client_id', v_client_id::text,
            'invoice_week_start', v_week_start::text,
            'mode', v_mode,

            'invoice_status_before', v_prev_status,
            'invoice_status_after', (select i.status::text from public.invoices i where i.id = v_invoice_id limit 1),

            'prev_subtotal_ex_vat', public._inv_round2(v_prev_ex),
            'prev_vat_amount', public._inv_round2(v_prev_vat),
            'prev_total_inc_vat', public._inv_round2(v_prev_inc),

            'delta_subtotal_ex_vat', v_delta_ex,
            'delta_vat_amount', v_delta_vat,
            'delta_total_inc_vat', v_delta_inc,

            'new_subtotal_ex_vat', public._inv_round2(v_new_ex),
            'new_vat_amount', public._inv_round2(v_new_vat),
            'new_total_inc_vat', public._inv_round2(v_new_inc),

            'timesheet_ids_this_run', to_jsonb(coalesce(v_run_ts_ids, array[]::uuid[])),
            'source_keys_this_run', to_jsonb(coalesce(v_run_source_keys, array[]::text[])),
            'line_count_this_run', coalesce(v_run_line_count,0)
          ),
          'invoices',
          v_invoice_id::text,
          jsonb_build_object(
            'subtotal_ex_vat', public._inv_round2(v_prev_ex),
            'vat_amount', public._inv_round2(v_prev_vat),
            'total_inc_vat', public._inv_round2(v_prev_inc)
          ),
          'RUN_TOTALS_DELTA',
          v_ip, v_ua, v_corr
        );
      end if;

          -- Lock segments (mirror JS lockSegmentsForInvoice) using segmentRefs built from entries
          select jsonb_agg(
            jsonb_build_object(
              'tsfin_id', e->>'tsfin_id',
              'timesheet_id', e->>'timesheet_id',
              'segment_id', (e->'segment'->>'segment_id'),
              'basis', e->>'basis'
            )
          )
          into meta
          from jsonb_array_elements(v_entries) e;

          perform public._inv_lock_segments_for_invoice(v_invoice_id, meta);

          -- AUDIT: TIMESHEET_SEGMENTS_INVOICED (per timesheet)
          for v_ts_id in
            select distinct (e->>'timesheet_id')::uuid
            from jsonb_array_elements(v_entries) e
          loop
            -- segment_count and sums based on HOURS_* lines inserted
            select
              count(*)::int,
              coalesce(sum(l.total_charge_ex_vat),0)::numeric,
              coalesce(sum(l.total_pay_ex_vat),0)::numeric
            into v_terms_days, chg_ex, pay_ex
            from public.invoice_lines l
            where l.invoice_id = v_invoice_id
              and l.timesheet_id = v_ts_id
              and upper(coalesce(l.meta_json->>'line_type','')) in ('HOURS_DAILY','HOURS_WEEKLY');

            -- bases: DAILY if any HOURS_DAILY exists; else first basis in entries order for this ts
            select exists(
              select 1 from public.invoice_lines l
              where l.invoice_id = v_invoice_id
                and l.timesheet_id = v_ts_id
                and upper(coalesce(l.meta_json->>'line_type','')) = 'HOURS_DAILY'
            ) into bydate_any;

            if bydate_any then
              meta := to_jsonb(array['DAILY']::text[]);
            else
              select to_jsonb(array[ upper(coalesce(e->>'basis','WEEKLY')) ]::text[])
              into meta
              from jsonb_array_elements(v_entries) e
              where (e->>'timesheet_id')::uuid = v_ts_id
              order by (e->>'entry_ord')::int asc
              limit 1;
            end if;

            perform public._inv_write_audit(
              p_actor_user_id,
              'TIMESHEET_SEGMENTS_INVOICED',
              jsonb_build_object(
                'timesheet_id', v_ts_id::text,
                'invoice_id', v_invoice_id::text,
                'invoice_week_start', v_week_start::text,
                'segment_count', v_terms_days,
                'total_charge_ex_vat', public._inv_round2(chg_ex),
                'total_pay_ex_vat', public._inv_round2(pay_ex),
                'bases', coalesce(meta, '[]'::jsonb)
              ),
              'timesheets',
              v_ts_id::text,
              null,
              null,
              v_ip, v_ua, v_corr
            );
          end loop;

          -- Mark weeks invoiced where fully locked (matches JS: locked_by_invoice_id=invoice.id)
          select array_agg(distinct tf.timesheet_id)
          into v_timesheet_ids
          from public.timesheets_financials tf
          where tf.is_current = true
            and tf.locked_by_invoice_id = v_invoice_id
            and tf.timesheet_id is not null;

          if v_timesheet_ids is not null and coalesce(array_length(v_timesheet_ids,1),0) > 0 then
            update public.contract_weeks
            set status = 'INVOICED'::public.contract_week_status_enum,
                updated_at = v_now
            where timesheet_id = any(v_timesheet_ids);

            for v_ts_id in
              select unnest(v_timesheet_ids)
            loop
              perform public._inv_write_audit(
                p_actor_user_id,
                'TIMESHEET_INVOICED',
                jsonb_build_object(
                  'timesheet_id', v_ts_id::text,
                  'invoice_id', v_invoice_id::text,
                  'invoice_week_start', v_week_start::text
                ),
                'timesheets',
                v_ts_id::text,
                null,
                'LOCKED_BY_INVOICE',
                v_ip, v_ua, v_corr
              );
            end loop;
          end if;

              -- group completed successfully
              v_succeeded_any := true;
            exception when others then
              if v_consol_mode <> 'NONE' then
                raise;
              end if;

              -- restore outer-scope accumulators (DB changes are rolled back automatically for this group)
              v_outbox_invoice_ids := v_grp_invoice_ids_before;
              v_outbox_warnings := v_grp_warnings_before;
              v_invoice_id := v_grp_invoice_id_before;

              v_failed_ts_ids := array_cat(v_failed_ts_ids, grp.ts_ids);

              v_failed_groups := v_failed_groups || jsonb_build_array(
                jsonb_build_object(
                  'ts_ids', to_jsonb(grp.ts_ids),
                  'error', sqlerrm
                )
              );

              v_outbox_warnings := v_outbox_warnings || jsonb_build_array(
                jsonb_build_object(
                  'kind','GROUP_FAILED',
                  'ts_ids', to_jsonb(grp.ts_ids),
                  'error', sqlerrm
                )
              );

              continue;
            end;
          end loop;
          -- Option A: partial failures allowed only when consolidation mode is NONE (one invoice per timesheet)
          if v_consol_mode = 'NONE' and coalesce(array_length(v_failed_ts_ids,1),0) > 0 then

            -- de-duplicate failed ids (defensive)
            select coalesce(array_agg(distinct x), array[]::uuid[])
            into v_failed_ts_ids
            from unnest(v_failed_ts_ids) x;

            update public.invoice_jobs_outbox o
            set
              payload = jsonb_set(coalesce(o.payload,'{}'::jsonb), '{timesheet_ids}', to_jsonb(v_failed_ts_ids), true),
              next_attempt_at = now() + interval '5 minutes',
              last_error = 'PARTIAL_FAILURE'
            where o.id = v_outbox_id;

            outbox_id := v_outbox_id;
            ok := false;
            invoice_ids := v_outbox_invoice_ids;
            warnings := jsonb_build_object(
              'kind','BY_WEEK',
              'partial_failure', true,
              'succeeded_any', v_succeeded_any,
              'failed', v_failed_groups,
              'created_invoice_ids', v_outbox_invoice_ids,
              'warnings', v_outbox_warnings,
              'client_id', v_client_id::text,
              'invoice_week_start', v_week_start::text,
              'mode', v_mode
            );

            if v_invoice_debug then
              v_dbg_results := v_dbg_results || jsonb_build_array(
                jsonb_build_object(
                  'outbox_id', v_outbox_id::text,
                  'kind', coalesce(v_kind,''),
                  'client_id', coalesce(v_client_id::text,''),
                  'mode', coalesce(v_mode,''),
                  'debug', jsonb_build_object(
                    'partial_failure', true,
                    'failed_ts_ids', to_jsonb(v_failed_ts_ids),
                    'failed_groups', v_failed_groups,
                    'created_invoice_ids', v_outbox_invoice_ids
                  )
                )
              );
            end if;

            return next;
            continue;
          end if;

          foreach v_invoice_id in array coalesce(v_outbox_invoice_ids,array[]::uuid[]) loop
            perform public._ctms_assert_invoice_correction_lines_v1(
              v_invoice_id,p_actor_user_id,true,'INVOICE_GENERATE_FROM_OUTBOX'
            );
          end loop;

          -- SUCCESS: delete outbox row
          delete from public.invoice_jobs_outbox where id = v_outbox_id;

          outbox_id := v_outbox_id;
          ok := true;
          invoice_ids := v_outbox_invoice_ids;
          warnings := jsonb_build_object(
            'kind','BY_WEEK',
            'invoice_ids', v_outbox_invoice_ids,
            'invoice_id', v_invoice_id::text,
            'warnings', v_outbox_warnings,

            'client_id', v_client_id::text,
            'invoice_week_start', v_week_start::text,
            'mode', v_mode
          );
                if v_invoice_debug then
                  v_dbg_results := v_dbg_results || jsonb_build_array(
                    jsonb_build_object(
                      'outbox_id', v_outbox_id::text,
                      'kind', coalesce(v_kind,''),
                      'payload', coalesce(v_payload,'{}'::jsonb),
                      'decision_trace', jsonb_build_object(
                        'branch','BY_WEEK',
                        'client_id', case when v_client_id is null then null else v_client_id::text end,
                        'invoice_week_start', case when v_week_start is null then null else v_week_start::text end,
                        'allow_early', coalesce(v_allow_early,false),
                        'consolidation_mode', v_consol_mode,
                        'all_selfbill', coalesce(v_all_selfbill,false),
                        'mode', v_mode,
                        'limit_ts_ids', case when v_limit_ts_ids is null then null else to_jsonb(v_limit_ts_ids) end,
                        'entries_count', v_entry_count,
                        'entries_timesheet_ids', to_jsonb(v_timesheet_ids),
                        'meta_count', coalesce(v_dbg_meta_count,0),
                        'meta_sample', coalesce(v_dbg_meta_sample,'[]'::jsonb),
                        'entries_sample', coalesce(v_dbg_entries_sample,'[]'::jsonb),
                        'timesheet_ids_pre_grouping', to_jsonb(coalesce(v_dbg_timesheet_ids_pre, array[]::uuid[])),
                        'ts_ids_to_use_pre_grouping', case when v_dbg_ts_ids_to_use_pre is null then null else to_jsonb(v_dbg_ts_ids_to_use_pre) end,
                        'groups_count', coalesce(v_dbg_groups_count,0),
                        'groups_rows', coalesce(v_dbg_groups_rows,'[]'::jsonb),
                        'groups_reason', v_dbg_groups_reason,
                        'groups_detail', coalesce(v_dbg_groups_detail,'[]'::jsonb),
                        'created_invoice_ids', to_jsonb(v_outbox_invoice_ids),
                        'invoice_summaries', (
                          select coalesce(jsonb_agg(
                            jsonb_build_object(
                              'invoice_id', i.id::text,
                              'invoice_no', i.invoice_no,
                              'status', i.status::text,
                              'subtotal_ex_vat', coalesce(i.subtotal_ex_vat,0)::numeric,
                              'vat_amount', coalesce(i.vat_amount,0)::numeric,
                              'total_inc_vat', coalesce(i.total_inc_vat,0)::numeric,
                              'line_count', (select count(*) from public.invoice_lines l where l.invoice_id=i.id)
                            )
                            order by i.created_at desc nulls last
                          ), '[]'::jsonb)
                          from public.invoices i
                          where i.id = any(v_outbox_invoice_ids)
                        )
                      ),
                      'result', jsonb_build_object(
                        'ok', ok,
                        'invoice_ids', case when invoice_ids is null then null else to_jsonb(invoice_ids) end,
                        'warnings', warnings
                      ),
                      'job_row', jsonb_build_object(
                        'attempt_count', coalesce(v_dbg_job_attempt_count,0),
                        'next_attempt_at', to_jsonb(v_dbg_job_next_attempt_at),
                        'last_error', v_dbg_job_last_error,
                        'created_at', to_jsonb(v_dbg_job_created_at)
                      ),
                      'timing', jsonb_build_object(
                        'now_utc', public._inv_iso_utc(v_now),
                        'anchor_ymd', v_anchor_ymd::text
                      ),
                      'audit_meta', jsonb_build_object(
                        'ip', v_ip,
                        'user_agent', v_ua,
                        'correlation_id', v_corr
                      )
                    )
                  );

                  if v_dbg_first_ip is null and v_ip is not null then v_dbg_first_ip := v_ip; end if;
                  if v_dbg_first_ua is null and v_ua is not null then v_dbg_first_ua := v_ua; end if;
                  if v_dbg_first_corr is null and v_corr is not null then v_dbg_first_corr := v_corr; end if;
                end if;
          return next;
          continue;
        end;

      else
        raise exception 'Unsupported invoice outbox kind: %', v_kind;
      end if;

blocks.handler:
exception when others then
  get stacked diagnostics v_state=returned_sqlstate,v_msg=message_text,v_detail=pg_exception_detail;
  if v_state in('55P03','57014') then
    return jsonb_build_object('ok',false,'success',false,'error_code','LOCK_TIMEOUT',
      'sqlstate',v_state,'detail',v_detail);
  end if;
  return jsonb_build_object('ok',false,'success',false,
    'error_code',coalesce(nullif(v_msg,''),v_state),
    'message',coalesce(nullif(v_msg,''),'Attach failed'),
    'sqlstate',v_state,'detail',v_detail,'queue_id',p_queue_id,'timesheet_id',p_timesheet_id);
end

blocks.protectedBody:
begin
  perform set_config('lock_timeout','2500ms',true);

  if coalesce(auth.role(),'')<>'service_role' then
    if auth.uid() is null or p_actor_user_id is distinct from auth.uid() then
      raise exception using errcode='42501',message='AUTHENTICATED_ACTOR_REQUIRED';
    end if;
  end if;
  if p_actor_user_id is null or not exists(
    select 1 from public.tms_users u where u.id=p_actor_user_id and u.is_active
  ) then
    raise exception using errcode='42501',message='ACTIVE_ACTOR_REQUIRED';
  end if;
  select lower(btrim(coalesce(u.role,''))) into v_actor_role
  from public.tms_users u where u.id=p_actor_user_id and u.is_active;
  if v_actor_role<>'admin' then
    raise exception using errcode='42501',message='TIMESHEET_ADMIN_REQUIRED';
  end if;

  if p_queue_id is null then return jsonb_build_object('ok',false,'error_code','QUEUE_ID_REQUIRED'); end if;
  if p_timesheet_id is null then return jsonb_build_object('ok',false,'error_code','TIMESHEET_ID_REQUIRED'); end if;
  if p_expected_timesheet_id is null then return jsonb_build_object('ok',false,'error_code','EXPECTED_TIMESHEET_ID_REQUIRED'); end if;
  if v_expected_key is null then return jsonb_build_object('ok',false,'error_code','QUEUE_ITEM_STORAGE_REQUIRED'); end if;

  if v_kind in('','TS') then v_kind:='TIMESHEET';
  elsif v_kind in('EXPENSE','EXPENSES') then v_kind:='TRAVEL';
  elsif v_kind in('MILES','MILE') then v_kind:='MILEAGE';
  elsif v_kind='ACCOM' then v_kind:='ACCOMMODATION'; end if;
  if v_kind not in('TIMESHEET','MILEAGE','TRAVEL','ACCOMMODATION','OTHER') then
    return jsonb_build_object('ok',false,'error_code','INVALID_EVIDENCE_KIND','kind',p_kind);
  end if;

  select * into v_ts
  from public.timesheets
  where timesheet_id=p_timesheet_id and is_current
  for update;
  if not found then return jsonb_build_object('ok',false,'error_code','TIMESHEET_NOT_FOUND'); end if;
  if v_ts.timesheet_id is distinct from p_expected_timesheet_id then
    return jsonb_build_object('ok',false,'error_code','TIMESHEET_MOVED',
      'current_timesheet_id',v_ts.timesheet_id,'expected_timesheet_id',p_expected_timesheet_id);
  end if;

  if exists(
    select 1 from public.timesheets_financials tf
    where tf.timesheet_id=v_ts.timesheet_id and tf.is_current
      and(
        tf.locked_by_invoice_id is not null
        or exists(
          select 1 from jsonb_array_elements(
            case when jsonb_typeof(tf.invoice_breakdown_json->'segments')='array'
              then tf.invoice_breakdown_json->'segments' else '[]'::jsonb end) seg(value)
          where nullif(btrim(seg.value->>'invoice_locked_invoice_id'),'') is not null))
  ) then
    return jsonb_build_object(
      'ok',false,'error_code','TIMESHEET_DOCUMENT_LOCKED');
  end if;

  if lower(coalesce(public._ctms_import_correction_classify_v1(v_ts.timesheet_id)
      ->>'is_import_authoritative_correction','false')) in('true','t','1','yes') then
    return jsonb_build_object(
      'ok',false,'error_code','IMPORT_AUTHORITATIVE_EVIDENCE_READ_ONLY');
  end if;

  if v_kind='TIMESHEET' and exists(
    select 1 from public.v_timesheets_summary_base s
    where s.timesheet_id=v_ts.timesheet_id
      and(coalesce(s.client_no_timesheet_required,false)
        or coalesce(s.client_is_nhsp,false))
  ) then
    return jsonb_build_object(
      'ok',false,'error_code','TIMESHEET_EVIDENCE_NOT_PERMITTED');
  end if;

  -- CloudTMS staff access is represented by an active tms_users record.  The
  -- queue item and current-timesheet locks below are the entity-scoped authority:
  -- callers cannot attach an object to a different or superseded timesheet.
  select * into v_queue
  from public.manual_timesheet_queue
  where id=p_queue_id
  for update;
  if not found then return jsonb_build_object('ok',false,'error_code','QUEUE_ITEM_NOT_AVAILABLE'); end if;
  v_key:=nullif(regexp_replace(coalesce(btrim(v_queue.r2_key),''),'^/+','','g'),'');
  if v_key is null or v_key is distinct from v_expected_key then
    return jsonb_build_object('ok',false,'error_code','QUEUE_ITEM_STORAGE_MISMATCH',
      'expected_storage_key',v_expected_key,'storage_key',v_key);
  end if;
  if upper(coalesce(v_queue.status,''))<>'QUEUED' or v_queue.timesheet_id is not null then
    return jsonb_build_object('ok',false,'error_code','QUEUE_ITEM_NOT_AVAILABLE',
      'status',v_queue.status,'timesheet_id',v_queue.timesheet_id);
  end if;

  if v_kind='TIMESHEET' and exists(
    select 1 from public.timesheet_evidence te
    where te.timesheet_id=v_ts.timesheet_id and upper(te.kind)='TIMESHEET'
      and regexp_replace(te.storage_key,'^/+','','g') is distinct from v_key
  ) then
    return jsonb_build_object('ok',false,'error_code','TIMESHEET_EVIDENCE_ALREADY_EXISTS');
  end if;

  select te.id into v_evidence_id
  from public.timesheet_evidence te
  where te.timesheet_id=v_ts.timesheet_id and upper(te.kind)=v_kind
    and regexp_replace(te.storage_key,'^/+','','g')=v_key
  order by te.created_at desc,te.id desc
  limit 1 for update;

  v_display_name:=coalesce(nullif(btrim(v_queue.original_filename),''),
    reverse(split_part(reverse(v_key),'/',1)));
  v_rotation_raw:=((coalesce(v_queue.last_rotation_deg,0)%360)+360)%360;
  v_rotation:=case when v_rotation_raw>=315 or v_rotation_raw<45 then 0
    when v_rotation_raw<135 then 90 when v_rotation_raw<225 then 180 else 270 end;
  v_revision:=encode(digest(concat_ws('|',v_ts.timesheet_id::text,v_kind,v_key,
    coalesce(v_queue.content_hash,''),v_rotation::text),'sha256'),'hex');

  if v_evidence_id is null then
    insert into public.timesheet_evidence(
      timesheet_id,kind,display_name,storage_key,created_at,created_by,
      source_revision,processing_state
    ) values(
      v_ts.timesheet_id,v_kind,v_display_name,v_key,v_now,p_actor_user_id,
      v_revision,'DISCOVERED'
    ) returning id into v_evidence_id;
    v_evidence_inserted:=true;
  else
    update public.timesheet_evidence
    set source_revision=v_revision
    where id=v_evidence_id and source_revision is distinct from v_revision;
  end if;

  select a.id,a.status,a.operation_id,a.normalised_r2_key,a.error_json
    into v_asset_id,v_asset_state,v_operation_id,v_normalised_r2_key,v_asset_error
  from public.invoice_document_assets a
  where a.source_kind='TIMESHEET_EVIDENCE' and a.source_id=v_evidence_id
    and a.source_revision=v_revision and a.original_r2_key=v_key
  for update;

  if found then
    v_asset_reused:=true;
  else
    insert into public.invoice_document_assets(
      source_kind,source_id,source_revision,original_r2_key,original_filename,
      declared_media_type,original_sha256,orientation_degrees,status,
      created_at_utc,updated_at_utc
    ) values(
      'TIMESHEET_EVIDENCE',v_evidence_id,v_revision,v_key,v_display_name,
      v_queue.mime_type,v_queue.content_hash,v_rotation,'DISCOVERED',v_now,v_now
    ) returning id,status into v_asset_id,v_asset_state;
  end if;
  v_asset_ready:=v_asset_state='READY';
  v_terminal_asset:=v_asset_state in(
    'UNSUPPORTED','CORRUPT','MISSING','FAILED','SUPERSEDED');

  if not v_asset_ready and not v_terminal_asset then
    select o.id into v_operation_id
    from public.invoice_operations o
    where o.operation_type='PREPARE_ASSET'
      and o.entity_type='DOCUMENT_ASSET' and o.entity_id=v_asset_id
      and o.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT')
    order by o.created_at_utc desc limit 1 for update;

    if v_operation_id is null
       and v_asset_reused
       and v_asset_state in('INSPECTING','NORMALISING') then
      raise exception using errcode='55000',
        message='ASSET_WORKFLOW_INCONSISTENT';
    end if;

    if v_operation_id is null then
      insert into public.invoice_operations(
        operation_type,entity_type,entity_id,actor_user_id,idempotency_key,status,phase,
        priority,source_revision,input_json,config_json,progress_json,total_units,chunk_count,
        control_version,change_seq,created_at_utc,updated_at_utc
      ) values(
        'PREPARE_ASSET','DOCUMENT_ASSET',v_asset_id,p_actor_user_id,
        encode(digest('PREPARE_ASSET|'||v_asset_id||'|'||v_revision,'sha256'),'hex'),
        'QUEUED','INSPECT',550,v_revision,
        jsonb_build_object('asset_id',v_asset_id,'source_kind','TIMESHEET_EVIDENCE',
          'source_id',v_evidence_id,'source_revision',v_revision,
          'original_r2_key',v_key,'original_filename',v_display_name,
          'declared_media_type',v_queue.mime_type,'rotation_degrees',v_rotation),
        jsonb_build_object('processor_policy',private._invoice_processor_limits()),
        jsonb_build_object('status_message','Asset queued for inspection'),
        1,1,1,nextval('public.invoice_operation_change_seq'),v_now,v_now
      ) returning id into v_operation_id;
    else
      update public.invoice_operations set priority=greatest(priority,550),
        change_seq=nextval('public.invoice_operation_change_seq'),updated_at_utc=v_now
      where id=v_operation_id;
    end if;

    update public.invoice_document_assets
    set operation_id=v_operation_id,updated_at_utc=v_now
    where id=v_asset_id and status<>'READY';

    insert into public.invoice_operation_chunks(
      operation_id,chunk_type,phase,work_key,sequence_no,entity_type,entity_id,
      document_asset_id,status,priority,run_after_utc,payload_json,
      operation_control_version,created_at_utc,updated_at_utc
    )
    select v_operation_id,'ASSET_INSPECT','INSPECT',
      encode(digest(concat_ws('|','ASSET_INSPECT',v_asset_id::text,v_revision,
        private._invoice_processor_limits()->>'policy_version'),'sha256'),'hex'),
      0,'DOCUMENT_ASSET',v_asset_id,
      v_asset_id,'QUEUED',550,v_now,
      jsonb_build_object('source_kind','TIMESHEET_EVIDENCE',
        'source_id',v_evidence_id,'source_revision',v_revision,'original_r2_key',v_key),
      o.control_version,v_now,v_now
    from public.invoice_operations o
    where o.id=v_operation_id
      and not exists(
        select 1 from public.invoice_operation_chunks ac
        where ac.document_asset_id=v_asset_id and ac.chunk_type in('ASSET_INSPECT','ASSET_NORMALISE')
          and ac.status in('QUEUED','RUNNING','WAITING','RETRY_WAIT')
      )
    on conflict(operation_id,chunk_type,level_no,sequence_no,work_key) do nothing;
  else
    v_operation_id:=null;
  end if;

  update public.timesheet_evidence
  set document_asset_id=v_asset_id,processing_state=v_asset_state,
    processing_error_json=case when v_terminal_asset then v_asset_error else null end
  where id=v_evidence_id;

  if v_kind='TIMESHEET' then
    update public.timesheets
    set manual_document_asset_id=v_asset_id,
      manual_pdf_r2_key=null,
      manual_pdf_rotation_degrees=v_rotation,
      document_state=case when v_terminal_asset then 'FAILED' else 'QUEUED' end,
      last_document_error_json=case when v_terminal_asset then v_asset_error else null end,
      updated_at=v_now
    where timesheet_id=v_ts.timesheet_id and is_current
    returning document_revision into v_document_revision;
  else
    select t.document_revision into v_document_revision
    from public.timesheets t
    where t.timesheet_id=v_ts.timesheet_id and t.is_current;
  end if;

  if not v_terminal_asset then
      select v.id,v.operation_id,v.status,v.r2_key
        into v_document_version_id,v_document_operation_id,
          v_document_status,v_document_r2_key
      from public.invoice_document_versions v
      where v.entity_type='TIMESHEET' and v.entity_id=v_ts.timesheet_id
        and v.purpose='TIMESHEET'
        and v.source_revision=v_document_revision::text
        and v.template_version='timesheet-professional-v1'
        and v.status in(
          'PLANNING','WAITING_FOR_INPUTS','RENDERING',
          'ASSEMBLING','VERIFYING','READY')
      order by(v.status='READY') desc,v.created_at_utc desc,v.id desc
      limit 1;

      if v_document_status='READY' then
        update public.timesheets t
        set current_document_version_id=v_document_version_id,
            manual_pdf_r2_key=v_document_r2_key,
            document_state='READY',
            active_document_operation_id=case
              when t.active_document_operation_id=v_document_operation_id
              then null else t.active_document_operation_id end,
            last_document_error_json=null,updated_at=v_now
        where t.timesheet_id=v_ts.timesheet_id and t.is_current
          and t.document_revision=v_document_revision;
      elsif v_document_version_id is null then
        v_document_idempotency:=encode(digest(concat_ws('|',
          'BUILD_DOCUMENT','TIMESHEET',v_ts.timesheet_id::text,'TIMESHEET',
          v_document_revision::text,'timesheet-professional-v1'),
          'sha256'),'hex');

        insert into public.invoice_operations(
          operation_type,entity_type,entity_id,actor_user_id,idempotency_key,
          status,phase,priority,source_revision,template_version,input_json,
          config_json,progress_json,total_units,chunk_count,control_version,
          change_seq,created_at_utc,updated_at_utc
        ) values(
          'BUILD_DOCUMENT','TIMESHEET',v_ts.timesheet_id,p_actor_user_id,
          v_document_idempotency,'QUEUED','BUILD_MANIFEST',550,
          v_document_revision::text,'timesheet-professional-v1',
          jsonb_build_object(
            'entity_type','TIMESHEET','entity_id',v_ts.timesheet_id,
            'purpose','TIMESHEET','source_revision',v_document_revision,
            'template_version','timesheet-professional-v1'),
          jsonb_build_object('processor_policy',private._invoice_processor_limits()),
          jsonb_build_object('status_message','Timesheet document queued'),
          1,1,1,nextval('public.invoice_operation_change_seq'),v_now,v_now
        )
        on conflict do nothing
        returning id into v_document_operation_id;

        if v_document_operation_id is null then
          select o.id into v_document_operation_id
          from public.invoice_operations o
          where o.idempotency_key=v_document_idempotency
            and o.status in(
              'QUEUED','RUNNING','WAITING','RETRY_WAIT')
          order by o.created_at_utc desc,o.id desc
          limit 1;
        end if;

        insert into public.invoice_document_versions(
          entity_type,entity_id,purpose,operation_id,source_revision,
          template_version,status,snapshot_json,snapshot_hash,
          manifest_json,manifest_hash,created_at_utc
        ) values(
          'TIMESHEET',v_ts.timesheet_id,'TIMESHEET',
          v_document_operation_id,v_document_revision::text,
          'timesheet-professional-v1','PLANNING','{}'::jsonb,
          encode(digest('{}','sha256'),'hex'),'[]'::jsonb,
          encode(digest('[]','sha256'),'hex'),v_now
        )
        on conflict(entity_type,entity_id,purpose,source_revision,template_version)
          where purpose in('DRAFT_PREVIEW','TIMESHEET')
            and status in(
              'PLANNING','WAITING_FOR_INPUTS','RENDERING',
              'ASSEMBLING','VERIFYING','READY')
        do nothing
        returning id into v_document_version_id;

        if v_document_version_id is null then
          select v.id,v.operation_id into
            v_document_version_id,v_document_operation_id
          from public.invoice_document_versions v
          where v.entity_type='TIMESHEET' and v.entity_id=v_ts.timesheet_id
            and v.purpose='TIMESHEET'
            and v.source_revision=v_document_revision::text
            and v.template_version='timesheet-professional-v1'
            and v.status in(
              'PLANNING','WAITING_FOR_INPUTS','RENDERING',
              'ASSEMBLING','VERIFYING','READY')
          order by(v.status='READY') desc,v.created_at_utc desc,v.id desc
          limit 1;
        end if;

        insert into public.invoice_operation_chunks(
          operation_id,chunk_type,phase,work_key,sequence_no,entity_type,entity_id,
          document_version_id,status,priority,run_after_utc,payload_json,
          operation_control_version,created_at_utc,updated_at_utc
        )
        select v_document_operation_id,'DOCUMENT_PLAN','BUILD_MANIFEST',
          encode(digest(concat_ws('|','DOCUMENT_PLAN',v_document_version_id::text,
            v_document_revision::text,'timesheet-professional-v1','1'),
            'sha256'),'hex'),
          0,
          'TIMESHEET',v_ts.timesheet_id,v_document_version_id,'QUEUED',550,
          v_now,jsonb_build_object(
            'purpose','TIMESHEET','source_revision',v_document_revision,
            'template_version','timesheet-professional-v1'),
          o.control_version,v_now,v_now
        from public.invoice_operations o
        where o.id=v_document_operation_id
        on conflict(operation_id,chunk_type,level_no,sequence_no,work_key)
          do nothing;

        update public.timesheets t
        set current_document_version_id=v_document_version_id,
            active_document_operation_id=v_document_operation_id,
            document_state='QUEUED',last_document_error_json=null,
            updated_at=v_now
        where t.timesheet_id=v_ts.timesheet_id and t.is_current
          and t.document_revision=v_document_revision;
      else
        update public.timesheets t
        set current_document_version_id=v_document_version_id,
            active_document_operation_id=v_document_operation_id,
            document_state=case when v_document_status='PLANNING'
              then 'QUEUED' else 'PREPARING' end,
            last_document_error_json=null,updated_at=v_now
        where t.timesheet_id=v_ts.timesheet_id and t.is_current
          and t.document_revision=v_document_revision;
      end if;
  end if;

  update public.manual_timesheet_queue
  set status='ATTACHED',timesheet_id=v_ts.timesheet_id,r2_key=v_key,
    meta_json=coalesce(meta_json,'{}')||jsonb_build_object(
      'attached_kind',v_kind,'attached_to_timesheet_id',v_ts.timesheet_id,
      'attached_at_utc',v_now,'attached_storage_key',v_key,
      'asset_id',v_asset_id,'asset_operation_id',v_operation_id,
      'document_operation_id',v_document_operation_id,
      'source',p_source_json->>'source')
  where id=p_queue_id and status='QUEUED' and timesheet_id is null
    and regexp_replace(r2_key,'^/+','','g')=v_key;
  if not found then raise exception 'QUEUE_ITEM_NOT_AVAILABLE'; end if;

  return jsonb_build_object(
    'ok',true,'success',true,'attached',true,'queue_id',p_queue_id,
    'evidence_id',v_evidence_id,'timesheet_id',v_ts.timesheet_id,'kind',v_kind,
    'storage_key',v_key,'asset_id',v_asset_id,
    'operation_id',v_operation_id,'asset_operation_id',v_operation_id,
    'document_operation_id',v_document_operation_id,
    'document_version_id',v_document_version_id,
    'asset_state',v_asset_state,'processing_state',v_asset_state,
    'asset_reused',v_asset_reused,'asset_ready',v_asset_ready,
    'terminal_asset',v_terminal_asset,
    'terminal_error',case when v_terminal_asset then v_asset_error end,
    'retry_required',v_terminal_asset,
    'backend_should_nudge',
      v_operation_id is not null or v_document_operation_id is not null,
    'timesheet_document_revision',(select document_revision from public.timesheets
      where timesheet_id=v_ts.timesheet_id and is_current),
    'queue_item_consumed',true,
    'changed_domains',jsonb_build_array(
      'timesheet_evidence','manual_timesheet_queue','invoice_document_assets',
      case when v_kind='TIMESHEET' then 'timesheets' end,
      case when v_operation_id is not null then 'invoice_operations' end)
  );

